using System.Text.Json;
namespace HomeLibrary;
public sealed record CardInput(string BorrowerId="",string Pin="",string Id="",string Action="",string Code="");
public sealed record KioskInput(string Code="",string Pin="",string Name="",string Id="");
public sealed record SelfPreviewInput(string Code,bool Returning);
public static class SelfServiceEndpoints {
 const string StationCookie="__Host-car-kiosk",SessionCookie="__Host-car-kiosk-reader";
 static void Cookie(HttpContext c,string key,string value,int seconds)=>c.Response.Cookies.Append(key,value,new CookieOptions{HttpOnly=true,Secure=true,SameSite=SameSiteMode.Strict,Path="/",MaxAge=TimeSpan.FromSeconds(seconds)});
 public static void Map(WebApplication app,Settings settings,Store store,Func<HttpContext,bool> admin,Func<HttpContext,bool> mobile){
  bool Public(HttpContext c)=>c.Connection.LocalPort==settings.CatalogPort&&settings.PublicCatalogOrigin!=""&&!settings.RecoveryReviewRequired&&!settings.RecoveryRehearsal;
  foreach(var prefix in new[]{"/api","/mobile"}){
   bool Allowed(HttpContext c)=>prefix=="/api"?admin(c):mobile(c);
   app.MapGet(prefix+"/patron-cards",(HttpContext c,PatronCards cards)=>Allowed(c)?Results.Json(cards.List(store),Library.Json):Results.NotFound());
   app.MapPost(prefix+"/patron-cards",(CardInput input,HttpContext c,PatronCards cards)=>{if(!Allowed(c))return Results.NotFound();object result=new{changed=true};switch(input.Action){case "issue":result=cards.Issue(store,input.BorrowerId,input.Pin);break;case "pin":cards.ResetPin(store,input.BorrowerId,input.Pin);break;case "revoke":case "review":cards.ChangeCard(input.Id,input.Action);break;case "resolve":result=cards.Resolve(store,input.Code);break;default:throw new LibraryError("Choose a supported card action.");}return Results.Json(result,Library.Json);});
   app.MapPost(prefix+"/kiosks/pair",(KioskInput input,HttpContext c,PatronCards cards)=>Allowed(c)?Results.Json(cards.Pair(store,input.Name),Library.Json):Results.NotFound()).RequireRateLimiting("pair");
   app.MapPost(prefix+"/kiosks/revoke",(KioskInput input,HttpContext c,PatronCards cards)=>{if(!Allowed(c))return Results.NotFound();cards.RevokeStation(input.Id);return Results.Ok(new{revoked=true});});
  }
  object ForAccount(HttpContext c,BorrowerAccounts accounts,Func<BorrowerAccount,object> action){if(!Public(c))throw new LibraryError("Borrower self-service is unavailable.",404);var a=AccountEndpoints.Account(c,accounts);return accounts.WithActiveAccount(a.Id,store,action);}
  app.MapGet("/account/self-service",(HttpContext c,BorrowerAccounts accounts,PatronCards cards)=>Results.Json(ForAccount(c,accounts,a=>new{settings=store.Read().State.SelfService,card=cards.Digital(store,a.BorrowerId)}),Library.Json));
  app.MapPost("/account/self-service/preview",(SelfPreviewInput input,HttpContext c,BorrowerAccounts accounts)=>Results.Json(ForAccount(c,accounts,a=>store.SelfPreview(a.BorrowerId,input.Code,input.Returning,"borrower-pwa")),Library.Json)).RequireRateLimiting("personal-reading");
  foreach(var action in new[]{"checkout","return"}){var returning=action=="return";app.MapPost("/account/self-service/"+action,(SelfServiceInput input,HttpContext c,BorrowerAccounts accounts)=>Results.Json(ForAccount(c,accounts,a=>store.SelfCirculate(a.BorrowerId,input,returning,"borrower-pwa")),Library.Json)).RequireRateLimiting("personal-reading");}
  app.MapGet("/kiosk/state",(HttpContext c,PatronCards cards)=>{if(!Public(c))return Results.NotFound();var s=store.Read().State;object? station=null;try{station=cards.StationStatus(store,c.Request.Cookies[StationCookie]);}catch(LibraryError){}return Results.Json(new{s.LibraryName,s.BannerSubtitle,settings=s.SelfService,station},Library.Json);});
  app.MapPost("/kiosk/enroll",(KioskInput input,HttpContext c,PatronCards cards)=>{if(!Public(c))return Results.NotFound();Cookie(c,StationCookie,cards.Enroll(store,input.Code),30*86400);return Results.Ok(new{paired=true});}).RequireRateLimiting("pair");
  app.MapPost("/kiosk/verify",(KioskInput input,HttpContext c,PatronCards cards)=>{if(!Public(c))return Results.NotFound();cards.End(c.Request.Cookies[SessionCookie]);c.Response.Cookies.Delete(SessionCookie,new CookieOptions{Path="/",Secure=true});var (token,view)=cards.Verify(store,c.Request.Cookies[StationCookie],input.Code,input.Pin);Cookie(c,SessionCookie,token,300);return Results.Json(view,Library.Json);}).RequireRateLimiting("kiosk-verify");
  app.MapPost("/kiosk/preview",(SelfPreviewInput input,HttpContext c,PatronCards cards)=>{if(!Public(c))return Results.NotFound();try{return Results.Json(cards.AsBorrower(store,c.Request.Cookies[StationCookie],c.Request.Cookies[SessionCookie],(borrower,_)=>store.SelfPreview(borrower,input.Code,input.Returning,"kiosk")),Library.Json);}catch{cards.End(c.Request.Cookies[SessionCookie]);throw;}}).RequireRateLimiting("personal-reading");
  foreach(var action in new[]{"checkout","return"}){var returning=action=="return";app.MapPost("/kiosk/"+action,(SelfServiceInput input,HttpContext c,PatronCards cards)=>{if(!Public(c))return Results.NotFound();try{return Results.Json(cards.AsBorrower(store,c.Request.Cookies[StationCookie],c.Request.Cookies[SessionCookie],(borrower,station)=>store.SelfCirculate(borrower,input,returning,"kiosk",station)),Library.Json);}catch{cards.End(c.Request.Cookies[SessionCookie]);throw;}}).RequireRateLimiting("personal-reading");}
  app.MapPost("/kiosk/end",(HttpContext c,PatronCards cards)=>{if(!Public(c))return Results.NotFound();cards.End(c.Request.Cookies[SessionCookie]);c.Response.Cookies.Delete(SessionCookie,new CookieOptions{Path="/",Secure=true});return Results.Ok(new{ended=true});});
  app.MapGet("/kiosk/{**leaf}",(string? leaf,HttpContext c)=>{if(!Public(c))return Results.NotFound();if(c.Request.Path=="/kiosk")return Results.Redirect("/kiosk/");var file=leaf switch{null or ""=>"kiosk.html","kiosk.js"=>"kiosk.js","api-client.js"=>"api-client.js",_=>null};if(file==null)return Results.NotFound();c.Response.Headers["Content-Security-Policy"]="default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'";return Results.File(Path.Combine(app.Environment.ContentRootPath,"wwwroot",file),file.EndsWith(".html")?"text/html":"text/javascript");});
 }
}
